        uint256[] memory requestIds = new uint256[](length);
        for (uint256 i = 0; i < length; i++) {
            requestIds[i] = _requestIds[i];
        }
        return _queueRedeemRequests(requestIds);
    }

    function depositIdleToMarket() external onlyAuthorized {
        EvaStorage.Layout storage $ = EvaStorage.layout();
        uint256 idle = IERC20(asset()).balanceOf(address(this));
        if ($.pendingDebt != 0) revert Errors.PendingRequestsExist();
