// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import {EnumerableSet} from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

struct RequestDetails {
    address requestor;
    uint256 shareAmount;
    uint256 requestAmount;
    uint256 requestTime;
    uint32 expiry;
    bool isProcessed;
    address receiver;
}

library EvaStorage {
    using EnumerableSet for EnumerableSet.UintSet;

    bytes32 internal constant SLOT = keccak256("eva.vault.storage.v1");

    struct Layout {
        uint256 virtualAssets;
        uint256 virtualShares;
        address market;
        uint256 minAmount;
        address mastermind;
        address lzEndpoint;
        uint8 vaultDecimals;
        uint256 newRequestId;
        uint256 pendingDebt;
        mapping(uint256 => RequestDetails) requestMapping;
        mapping(uint32 => bool) batchProcessed;
        EnumerableSet.UintSet pendingRequestIds;
        uint32 activeBatchExpiry;
    }

    function layout() internal pure returns (Layout storage s) {
        bytes32 slot = SLOT;
        assembly {
            s.slot := slot
        }
    }
}

