// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import {ERC20Upgradeable} from "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import {OFTCoreUpgradeable} from "@layerzerolabs/oft-evm-upgradeable/contracts/oft/OFTCoreUpgradeable.sol";

/// @dev self-mint/burn OFT base for upgradeable EVA tokens.
///
/// EVA does not inherit LayerZero's stock `OFTUpgradeable` because the mainnet token
/// is also an ERC4626 vault. The vault needs its own ERC20/ERC4626 initialization,
/// virtual asset/share accounting, and custom bridge burn/mint logic.
///
/// This base keeps the LayerZero OFTCore path but takes `localDecimals_` directly.
/// That matters because LayerZero computes `decimalConversionRate` in the constructor,
/// and EVA deploys assets with different local decimals.
abstract contract EvaOFTUpgradeable is OFTCoreUpgradeable, ERC20Upgradeable {
    constructor(uint8 localDecimals_, address lzEndpoint_) OFTCoreUpgradeable(localDecimals_, lzEndpoint_) {}

    /// @dev iOFT hook: this contract is the bridged token.
    function token() public view virtual returns (address) {
        return address(this);
    }

    /// @dev iOFT hook: bridge sends burn caller balance, no approval needed.
    function approvalRequired() external pure virtual returns (bool) {
        return false;
    }

    function _debit(address _from, uint256 _amountLD, uint256 _minAmountLD, uint32 _dstEid)
        internal
        virtual
        override
        returns (uint256 amountSentLD, uint256 amountReceivedLD)
    {
        _assertOftConfig();
        (amountSentLD, amountReceivedLD) = _debitView(_amountLD, _minAmountLD, _dstEid);
        _burn(_from, amountSentLD);
    }

    function _credit(
        address _to,
        uint256 _amountLD,
        uint32 /* _srcEid */
    )
        internal
        virtual
        override
        returns (uint256 amountReceivedLD)
    {
        _assertOftConfig();
        if (_to == address(0)) _to = address(0xdead);
        _mint(_to, _amountLD);
        return _amountLD;
    }

    function _assertOftConfig() internal view virtual;
}

