// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import {EnumerableSet} from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";
import {EvaStorage, RequestDetails} from "../EvaStorage.sol";
import {IWildcat} from "../interfaces/IWildcat.sol";

/// @dev read-only wildcat withdrawal helper lib
library WildcatWithdrawalLib {
    using EnumerableSet for EnumerableSet.UintSet;

    function paidBacking(EvaStorage.Layout storage $, address account) internal view returns (uint256 totalBacking) {
        if ($.activeBatchExpiry != 0) {
            return paidBackingForExpiry($, account, $.activeBatchExpiry);
        }

        uint256 length = $.pendingRequestIds.length();
        uint32[] memory expiries = new uint32[](length);
        uint256 uniqueCount;

        for (uint256 i = 0; i < length; i++) {
            uint32 expiry = $.requestMapping[$.pendingRequestIds.at(i)].expiry;
            if (expiry == 0 || $.batchProcessed[expiry]) continue;

            bool alreadyCounted;
            for (uint256 j = 0; j < uniqueCount; j++) {
                if (expiries[j] == expiry) {
                    alreadyCounted = true;
                    break;
                }
            }

            if (alreadyCounted) continue;

            expiries[uniqueCount] = expiry;
            uniqueCount++;
            totalBacking += paidBackingForExpiry($, account, expiry);
        }
    }

    function pendingDebtForExpiry(EvaStorage.Layout storage $, uint32 expiry) internal view returns (uint256 amount) {
        uint256 length = $.pendingRequestIds.length();
        for (uint256 i = 0; i < length; i++) {
            RequestDetails storage request = $.requestMapping[$.pendingRequestIds.at(i)];
            if (request.expiry == expiry) {
                amount += request.requestAmount;
            }
        }
    }

    function paidBackingForExpiry(EvaStorage.Layout storage $, address account, uint32 expiry)
        internal
        view
        returns (uint256)
    {
        if (expiry == 0 || $.batchProcessed[expiry]) return 0;

        IWildcat.WithdrawalBatch memory batch = IWildcat($.market).getWithdrawalBatch(expiry);
        if (batch.scaledTotalAmount == 0 || batch.normalizedAmountPaid == 0) return 0;

        IWildcat.AccountWithdrawalStatus memory status = IWildcat($.market).getAccountWithdrawalStatus(account, expiry);
        if (status.scaledAmount == 0) return 0;

        uint256 entitledAmount =
            uint256(batch.normalizedAmountPaid) * uint256(status.scaledAmount) / uint256(batch.scaledTotalAmount);
        if (entitledAmount <= status.normalizedAmountWithdrawn) return 0;

        return entitledAmount - status.normalizedAmountWithdrawn;
    }

    function isWithdrawalBatchFullyPaid(EvaStorage.Layout storage $, uint32 expiry) internal view returns (bool) {
        IWildcat.WithdrawalBatch memory batch = IWildcat($.market).getWithdrawalBatch(expiry);
        return batch.scaledAmountBurned >= batch.scaledTotalAmount;
    }

    function hasPendingRequestsForExpiry(EvaStorage.Layout storage $, uint32 expiry) internal view returns (bool) {
        uint256 length = $.pendingRequestIds.length();
        for (uint256 i = 0; i < length; i++) {
            if ($.requestMapping[$.pendingRequestIds.at(i)].expiry == expiry) return true;
        }

        return false;
    }
}

