// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ERC20Upgradeable} from "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import {ERC4626Upgradeable} from "@openzeppelin/contracts-upgradeable/token/ERC20/extensions/ERC4626Upgradeable.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuardUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import {EnumerableSet} from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";
import {IWildcat} from "./interfaces/IWildcat.sol";
import {IEvaMasterMind} from "./interfaces/IEvaMasterMind.sol";
import {EvaStorage, RequestDetails} from "./EvaStorage.sol";
import {EvaOFTUpgradeable} from "./EvaOFTUpgradeable.sol";
import {Errors} from "./libraries/Errors.sol";
import {WildcatWithdrawalLib} from "./libraries/WildcatWithdrawalLib.sol";

/// @title EvaVault
/// @dev async erc4626 vault: deposits go straight into wildcat, exits go through
///      wildcat withdrawal batches, claims happen after settlement.
///      exchange rate is kept 1:1; excess yield is skimmed as protocol revenue.
///      virtual assets/shares are used so OFT burns do not change vault accounting.
contract EvaVault is ERC4626Upgradeable, EvaOFTUpgradeable, ReentrancyGuardUpgradeable {
    using SafeERC20 for IERC20;
    using EnumerableSet for EnumerableSet.UintSet;
    using WildcatWithdrawalLib for EvaStorage.Layout;

    uint8 private immutable _decimals;
    uint256 private constant RAY = 1e27;

    event RequestSubmitted(RequestDetails requestDetails, uint256 requestId);
    event RequestQueued(uint256 indexed requestId, uint32 expiry);
    event RequestProcessed(RequestDetails requestDetails, uint256 requestId);
    event RequestCancelled(uint256 indexed requestId);
    event IdleDeposited(uint256 amount);
    event Skimmed(address indexed operator, uint256 amount);

    modifier onlyAuthorized() {
        EvaStorage.Layout storage $ = EvaStorage.layout();
        IEvaMasterMind f = IEvaMasterMind($.mastermind);
        if (msg.sender != $.mastermind && msg.sender != f.governance() && msg.sender != f.operator()) {
            revert Errors.Unauthorized();
        }
        _;
    }

    /// @dev lz endpoint + decimal conversion are implementation immutables
    ///      create3 address parity is deployer + salt, not bytecode
    constructor(address _lzEndpoint, uint8 vaultDecimals_) EvaOFTUpgradeable(vaultDecimals_, _lzEndpoint) {
        _decimals = vaultDecimals_;
        _disableInitializers();
    }

    function initialize(
        string memory _name,
        string memory _symbol,
        address _underlying,
        address _market,
        uint256 _minAmount,
        address _mastermind,
        address _delegate
    ) external initializer {
        if (_underlying == address(0)) revert Errors.ZeroUnderlying();
        if (_market == address(0)) revert Errors.ZeroMarket();
        if (_mastermind == address(0)) revert Errors.ZeroMastermind();
        if (_delegate == address(0)) revert Errors.ZeroDelegate();
        if (_minAmount == 0) revert Errors.ZeroMinAmount();
        if (IWildcat(_market).asset() != _underlying) revert Errors.UnderlyingMismatch();
        if (IWildcat(_market).decimals() != _decimals) revert Errors.MarketDecimalsMismatch();

        __ERC20_init(_name, _symbol);
        __ERC4626_init(IERC20(_underlying));
        __OFTCore_init(_delegate);
        __Ownable_init(_delegate);
        __ReentrancyGuard_init();

        EvaStorage.Layout storage $ = EvaStorage.layout();
        $.market = _market;
        $.minAmount = _minAmount;
        $.mastermind = _mastermind;
        $.lzEndpoint = address(endpoint);
        $.vaultDecimals = _decimals;
    }

    // VIEW FUNCTIONS
    function decimals() public view override(ERC20Upgradeable, ERC4626Upgradeable) returns (uint8) {
        return _decimals;
    }

    /// @dev virtual asset side of 1:1 erc4626 accounting
    function totalAssets() public view override returns (uint256) {
        return EvaStorage.layout().virtualAssets;
    }

    /// @dev virtual share side of 1:1 erc4626 accounting
    function totalSupply() public view override(ERC20Upgradeable, IERC20) returns (uint256) {
        return EvaStorage.layout().virtualShares;
    }

    function market() external view returns (address) {
        return EvaStorage.layout().market;
    }

    function mastermind() external view returns (address) {
        return EvaStorage.layout().mastermind;
    }

    function minAmount() external view returns (uint256) {
        return EvaStorage.layout().minAmount;
    }

    /// @dev skim-able yield
    function excess() external view returns (uint256) {
        EvaStorage.Layout storage $ = EvaStorage.layout();
        return _excess($);
    }

    // ERC4626-LIKE FUNCTIONS
    function deposit(uint256 assets, address receiver) public override nonReentrant returns (uint256) {
        if (assets < EvaStorage.layout().minAmount) revert Errors.MinAmount();
        return super.deposit(assets, receiver);
    }

    function mint(uint256 shares, address receiver) public override nonReentrant returns (uint256) {
        uint256 assets = previewMint(shares);
        if (assets < EvaStorage.layout().minAmount) revert Errors.MinAmount();
        return super.mint(shares, receiver);
    }

    /// @dev Allows users to deposit already-minted wildcat market tokens into the vault in exchange for shares
    function depositFromMarket(uint256 marketAssets, address receiver) external nonReentrant returns (uint256 shares) {
        if (receiver == address(0)) revert Errors.ZeroReceiver();

        EvaStorage.Layout storage $ = EvaStorage.layout();
        IWildcat wildcat = IWildcat($.market);
        IERC20 marketToken = IERC20($.market);

        uint256 scaledBefore = wildcat.scaledBalanceOf(address(this));
        marketToken.safeTransferFrom(msg.sender, address(this), marketAssets);
        uint256 scaledAfter = wildcat.scaledBalanceOf(address(this));
        uint256 balanceAfter = wildcat.balanceOf(address(this));

        if (scaledAfter <= scaledBefore) revert Errors.MinAmount();
        uint256 scaledReceived = scaledAfter - scaledBefore;
        // Price only the scaled tokens received in this transfer, not accrual on the vault's prior balance.
        unchecked {
            shares = balanceAfter * scaledReceived / scaledAfter;
        }
        if (shares < $.minAmount) revert Errors.MinAmount();

        $.virtualAssets += shares;
        $.virtualShares += shares;
        _mint(receiver, shares);

        emit Deposit(msg.sender, receiver, shares, shares);
    }

    function _deposit(address caller, address receiver, uint256 assets, uint256 shares) internal override {
        EvaStorage.Layout storage $ = EvaStorage.layout();
        IERC20 underlying = IERC20(asset());

        underlying.safeTransferFrom(caller, address(this), assets);
        underlying.forceApprove($.market, assets);
        IWildcat($.market).deposit(assets);

        $.virtualAssets += assets;
        $.virtualShares += shares;
        _mint(receiver, shares);

        emit Deposit(caller, receiver, assets, shares);
    }

    function withdraw(uint256, address, address) public pure override returns (uint256) {
        revert();
    }

    function redeem(uint256, address, address) public pure override returns (uint256) {
        revert();
    }

    function requestRedeem(uint256 _amountOfShares) external nonReentrant {
        _requestRedeem(_amountOfShares, msg.sender);
    }

    function requestRedeemTo(uint256 _amountOfShares, address _receiver) external nonReentrant {
        _requestRedeem(_amountOfShares, _receiver);
    }

    function _requestRedeem(uint256 _amountOfShares, address _receiver) internal {
        EvaStorage.Layout storage $ = EvaStorage.layout();
        if (_receiver == address(0)) revert Errors.ZeroReceiver();

        uint256 expectedOutput = previewRedeem(_amountOfShares);
        if (expectedOutput < $.minAmount) revert Errors.MinAmount();

        _burn(msg.sender, _amountOfShares);
        $.virtualShares -= _amountOfShares;
        $.virtualAssets -= expectedOutput;

        $.pendingDebt += expectedOutput;

        uint256 requestId = $.newRequestId;
        RequestDetails memory request = RequestDetails({
            requestor: msg.sender,
            shareAmount: _amountOfShares,
            requestAmount: expectedOutput,
            requestTime: block.timestamp,
            expiry: 0,
            isProcessed: false,
            receiver: _receiver
        });
        $.requestMapping[requestId] = request;
        $.pendingRequestIds.add(requestId);

        emit RequestSubmitted(request, requestId);
        $.newRequestId++;
    }

    /// @dev Queued requests have a wildcat expiry. If Wildcat borrower does a partial repayment
    ///      anyone can claim the request, FCFS (first come first serve) by design.
    function claimRequest(uint256 _requestId) external nonReentrant {
        _finalizeQueuedRequest(_requestId);
    }

    /// @dev Allows the requestor to cancel before the request enters a withdrawal batch.
    function cancelRequest(uint256 _requestId) external nonReentrant {
        EvaStorage.Layout storage $ = EvaStorage.layout();
        RequestDetails storage request = $.requestMapping[_requestId];
        if (request.requestTime == 0) revert Errors.InvalidRequest();
        if (request.expiry != 0) revert Errors.AlreadyQueued();
        if (msg.sender != request.requestor) revert Errors.Unauthorized();

        uint256 shareAmount = request.shareAmount;
        uint256 requestAmount = request.requestAmount;

        $.pendingDebt -= requestAmount;
        $.pendingRequestIds.remove(_requestId);
        delete $.requestMapping[_requestId];
        $.virtualAssets += requestAmount;
        $.virtualShares += shareAmount;
        _mint(msg.sender, shareAmount);

        emit RequestCancelled(_requestId);
    }

    // INTERNAL HELPERS
    function _queueRedeemRequests(uint256[] memory _requestIds) internal returns (uint32 expiry) {
        EvaStorage.Layout storage $ = EvaStorage.layout();
        uint256 length = _requestIds.length;
        if (length == 0) revert Errors.NoRequests();

        _trySettleActiveBatch();
        if ($.activeBatchExpiry != 0) revert Errors.ActiveBatchExists();

        uint256 totalAmount;
        for (uint256 i = 0; i < length; i++) {
            for (uint256 j = 0; j < i; j++) {
                if (_requestIds[j] == _requestIds[i]) revert Errors.DuplicateRequest();
            }
            RequestDetails storage request = $.requestMapping[_requestIds[i]];
            if (request.requestTime == 0) revert Errors.InvalidRequest();
            if (request.expiry != 0) revert Errors.AlreadyQueued();
            totalAmount += request.requestAmount;
        }

        IWildcat wildcat = IWildcat($.market);
        uint256 scaleFactor = wildcat.scaleFactor();
        // Wildcat queues with half-up rayDiv but pays batches with floor mulDiv.
        uint256 targetAmount = scaleFactor > RAY ? totalAmount + 1 : totalAmount;
        uint256 queueAmount;
        unchecked {
            uint256 scaledAmount = (targetAmount * RAY + scaleFactor - 1) / scaleFactor;
            queueAmount = (scaledAmount * scaleFactor + RAY - 1) / RAY;
        }
        if (wildcat.balanceOf(address(this)) < queueAmount) revert Errors.InsufficientBalance();
        expiry = wildcat.queueWithdrawal(queueAmount);
        $.activeBatchExpiry = expiry;

        for (uint256 i = 0; i < length; i++) {
            uint256 requestId = _requestIds[i];
            $.requestMapping[requestId].expiry = expiry;
            emit RequestQueued(requestId, expiry);
        }
    }

    function _trySettleActiveBatch() internal {
        EvaStorage.Layout storage $ = EvaStorage.layout();
        uint32 expiry = $.activeBatchExpiry;
        if (expiry == 0) return;
        if (block.timestamp < expiry) return;

        IERC20 underlying = IERC20(asset());
        if ($.paidBackingForExpiry(address(this), expiry) != 0) {
            IWildcat($.market).executeWithdrawal(address(this), expiry);
        }

        if (!$.isWithdrawalBatchFullyPaid(expiry)) return;

        uint256 amount = $.pendingDebtForExpiry(expiry);
        if (underlying.balanceOf(address(this)) < amount) return;

        $.batchProcessed[expiry] = true;
        $.activeBatchExpiry = 0;
    }

    function _finalizeQueuedRequest(uint256 _requestId) internal {
        EvaStorage.Layout storage $ = EvaStorage.layout();
        RequestDetails storage request = $.requestMapping[_requestId];
        if (request.requestTime == 0) revert Errors.InvalidRequest();
        if (request.isProcessed) revert Errors.AlreadyProcessed();
        if (request.expiry == 0) revert Errors.RequestNotQueued();
        if (block.timestamp < request.expiry) revert Errors.RequestNotReady();

        uint256 requestAmount = request.requestAmount;
        request.isProcessed = true;

        $.pendingDebt -= requestAmount;
        $.pendingRequestIds.remove(_requestId);

        IERC20 underlying = IERC20(asset());
        if ($.paidBackingForExpiry(address(this), request.expiry) != 0) {
            IWildcat($.market).executeWithdrawal(address(this), request.expiry);
        }

        address recipient = request.receiver == address(0) ? request.requestor : request.receiver;
        if (underlying.balanceOf(address(this)) < requestAmount) revert Errors.InsufficientBalance();
        underlying.safeTransfer(recipient, requestAmount);

        if ($.isWithdrawalBatchFullyPaid(request.expiry) && !$.hasPendingRequestsForExpiry(request.expiry)) {
            $.batchProcessed[request.expiry] = true;
            if (request.expiry == $.activeBatchExpiry) {
                $.activeBatchExpiry = 0;
            }
        }

        RequestDetails memory processedRequest = request;
        processedRequest.receiver = recipient;
        emit RequestProcessed(processedRequest, _requestId);
    }

    function _depositIdleToMarket() internal {
        EvaStorage.Layout storage $ = EvaStorage.layout();
        IERC20 underlying = IERC20(asset());
        uint256 idle = underlying.balanceOf(address(this));
        if (idle >= $.minAmount) {
            underlying.forceApprove($.market, idle);
            IWildcat($.market).deposit(idle);
            emit IdleDeposited(idle);
        }
    }

    /// ADMIN FUNCTIONS
    function queueRequestsBatch(uint256[] calldata _requestIds)
        external
        nonReentrant
        onlyAuthorized
        returns (uint32 expiry)
    {
        uint256 length = _requestIds.length;
        uint256[] memory requestIds = new uint256[](length);
        for (uint256 i = 0; i < length; i++) {
            requestIds[i] = _requestIds[i];
        }
        return _queueRedeemRequests(requestIds);
    }

    function depositIdleToMarket() external onlyAuthorized {
        EvaStorage.Layout storage $ = EvaStorage.layout();
        uint256 idle = IERC20(asset()).balanceOf(address(this));
        if ($.pendingDebt != 0) revert Errors.PendingRequestsExist();
        if (idle < $.minAmount) revert Errors.InsufficientIdle();
        _depositIdleToMarket();
    }

    /// @dev mint excess yield to operator. ratio stays 1:1.
    function skim() external onlyAuthorized {
        EvaStorage.Layout storage $ = EvaStorage.layout();
        uint256 excessAmount = _excess($);
        if (excessAmount == 0) revert Errors.NothingToSkim();
        address operator = IEvaMasterMind($.mastermind).operator();
        if (operator == address(0)) revert Errors.ZeroAddress();

        $.virtualAssets += excessAmount;
        $.virtualShares += excessAmount;
        _mint(operator, excessAmount);

        emit Skimmed(operator, excessAmount);
    }

    function _excess(EvaStorage.Layout storage $) private view returns (uint256) {
        uint256 available = IERC20(asset()).balanceOf(address(this)) + IWildcat($.market).balanceOf(address(this))
            + $.paidBacking(address(this));
        uint256 owed = $.virtualAssets + $.pendingDebt;
        return available > owed ? available - owed : 0;
    }

    // LAYERZERO HELPERS
    /// @dev extra paranoid sanity check for implementation immutables after upgrades.
    function _assertOftConfig() internal view override {
        EvaStorage.Layout storage $ = EvaStorage.layout();
        if ($.lzEndpoint != address(endpoint)) revert Errors.LayerZeroEndpointMismatch();
        if ($.vaultDecimals != _decimals) revert Errors.LayerZeroDecimalsMismatch();
    }
}

src/EvaStorage.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import {EnumerableSet} from "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

struct RequestDetails {
    address requestor;
    uint256 shareAmount;
    uint256 requestAmount;
    uint256 requestTime;
    uint32 expiry;
    bool isProcessed;
    address receiver;
}

library EvaStorage {
    using EnumerableSet for EnumerableSet.UintSet;

    bytes32 internal constant SLOT = keccak256("eva.vault.storage.v1");

    struct Layout {
        uint256 virtualAssets;
        uint256 virtualShares;
        address market;
        uint256 minAmount;
        address mastermind;
        address lzEndpoint;
        uint8 vaultDecimals;
        uint256 newRequestId;
        uint256 pendingDebt;
        mapping(uint256 => RequestDetails) requestMapping;
        mapping(uint32 => bool) batchProcessed;
        EnumerableSet.UintSet pendingRequestIds;
        uint32 activeBatchExpiry;
    }

    function layout() internal pure returns (Layout storage s) {
        bytes32 slot = SLOT;
        assembly {
            s.slot := slot
        }
    }
}

